import {makeAutoObservable} from 'mobx'

import type {Guide, GuideId} from '../Guides.types'

import type {GuidesState} from './root'

export class AvailableGuidesState {
  root: GuidesState
  list: Array<Guide> = []

  constructor(root: GuidesState) {
    this.root = root

    makeAutoObservable(this, {
      root: false,
    })
  }

  setAvailableGuides(guides: Array<Guide>) {
    this.list = guides
  }

  registerGuide(guide: Guide) {
    if (guide && !this.list.find(item => item.id === guide.id)) {
      this.list.push(guide)
    }
  }

  getGuideById(guideId: GuideId): Guide | undefined {
    return this.list.find(item => item.id === guideId)
  }

  getGuideByProjectId(projectId: string): Guide | undefined {
    return this.list.find(item => item.projectId === projectId)
  }
}
