import shareIcon from '@jetbrains/icons/new-window'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import {AlertService} from '@jetbrains/teamcity-ui/dist/services'
import React from 'react'

import type {GuideId, GuideStep} from '../Guides.types'
import {createGuideShareLink} from '../Guides.utils'

import styles from './GuideItem.module.css'

const GuideItemShareLink = React.memo(({guideId, step}: {guideId: GuideId; step: GuideStep}) => {
  const ALERT_TIMEOUT = 1000

  const onClick = async () => {
    const url = await createGuideShareLink(guideId, step)

    await navigator.clipboard.writeText(url)
    AlertService.successMessage('Copied', ALERT_TIMEOUT)
  }

  return (
    <Tooltip title={'Copy guide start link to clipboard'}>
      <Button className={styles.shareLink} icon={shareIcon} onClick={onClick} />
    </Tooltip>
  )
})
GuideItemShareLink.displayName = 'ShareLink'
export default GuideItemShareLink
