import {
  ControlsHeight,
  ControlsHeightContext,
} from '@jetbrains/ring-ui-built/components/global/controls-height'
import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import TeamCityUtils from '@jetbrains/teamcity-ui/dist/utils'
import classNames from 'classnames'
import {observer} from 'mobx-react'
import React from 'react'

import Tags from '../../common/Tags/Tags'
import type {Guide, GuideId} from '../Guides.types'
import {launchGuide} from '../Guides.utils'
import guidesState from '../state/root'

import GuideBottomSection from './GuideItem.controls'
import GuideItemImage from './GuideItem.image'
import ShareLink from './GuideItem.sharelink'

import styles from './GuideItem.module.css'

type OwnProps = Guide & {
  readonly compact?: boolean
  readonly disableStartLink?: boolean
  readonly onStart?: (guideId: GuideId) => void
  readonly onReset?: (guideId: GuideId) => void
}

function noop() {}
const GuideItem = observer(
  ({
    compact,
    disableStartLink,
    onStart: onStartExternal = noop,
    onReset: onResetExternal = noop,
    ...guide
  }: OwnProps): React.ReactElement => {
    const {projectId, id, title, className, description, image, duration, tags, steps} = guide
    const progress = guidesState.progress?.findByGuideId(id)

    const [projectName, setProjectName] = React.useState<string | null>(null)
    const baseProjectURL = projectId ? `${window.base_uri}/project/${projectId}` : null

    const classes = classNames(styles.guide, compact ? styles.short : null, className)
    const onStart = React.useCallback(() => {
      launchGuide(id)
      onStartExternal(id)
    }, [id, onStartExternal])

    const onReset = React.useCallback(() => {
      guidesState.progress.resetProgress(id)
      onResetExternal(id)
    }, [id, onResetExternal])

    React.useEffect(() => {
      async function fetchProjectData() {
        try {
          const projectData = await TeamCityUtils.requestJSON<{name: string}>(
            `app/rest/projects/id:${projectId}?fields=name`,
          )

          if (projectData.name) {
            setProjectName(projectData.name)
          }
          // eslint-disable-next-line no-empty
        } catch (error) {}
      }

      if (projectId) {
        fetchProjectData().then()
      }
    }, [projectId])

    return (
      <ControlsHeightContext.Provider value={ControlsHeight.S}>
        <div className={classes} data-guide-id={id}>
          <div className={styles.top}>
            <Link
              onClick={onStart}
              disabled={disableStartLink}
              className={disableStartLink ? styles.disabled : ''}
            >
              <GuideItemImage key={'image'} {...image} />
              <H3 key={'title'} className={styles.title}>
                {title}
              </H3>
            </Link>
            <ShareLink guideId={id} step={steps[0]} />
          </div>
          {baseProjectURL != null && (
            <span>
              {'Based on '}
              {projectName != null ? (
                <Link href={baseProjectURL}>{projectName}</Link>
              ) : (
                <LoaderInline />
              )}
            </span>
          )}
          {!compact && <div className={styles.description}>{description}</div>}
          <GuideBottomSection
            onStart={onStart}
            onReset={onReset}
            completed={progress?.completed.length ?? 0}
            totalSteps={steps.length}
            duration={duration}
          />
          <Tags tags={tags} />
        </div>
      </ControlsHeightContext.Provider>
    )
  },
)

export default GuideItem
