import Button from '@jetbrains/ring-ui-built/components/button/button'
import {observer} from 'mobx-react'
import plur from 'plur'
import React from 'react'

import styles from './GuideItem.module.css'

const INIT_BTN_TEXT = 'Start lesson'
const ONGOING_BTN_TEXT = 'Continue'
const COMPLETED_BTN_TEXT = 'Start again'

const GuideBottomSection = observer(
  ({
    completed,
    totalSteps,
    duration,
    onStart: start = () => {},
    onReset: reset = () => {},
  }: {
    completed: number
    totalSteps: number
    duration: number
    onStart: () => void
    onReset: () => void
  }) => {
    const content = React.useMemo(() => {
      let caption = COMPLETED_BTN_TEXT
      let description = 'You have passed the lesson'

      if (completed === 0) {
        caption = INIT_BTN_TEXT
        description = `${totalSteps} steps, ≈${duration} minutes`
      } else if (completed < totalSteps) {
        caption = ONGOING_BTN_TEXT
        description = `You completed ${completed} ${plur('step', completed)} of ${totalSteps}`
      }

      return {caption, description}
    }, [duration, totalSteps, completed])

    return (
      <div className={styles.bot}>
        <Button onClick={start} data-guide-start>
          {content.caption}
        </Button>
        <span className={styles.progressInfo}>{content.description}</span>
        {content.caption === ONGOING_BTN_TEXT && (
          <Button inline className={styles.reset} onClick={reset} data-guide-reset>
            {'(reset)'}
          </Button>
        )}
      </div>
    )
  },
)

export default GuideBottomSection
