import getUID from '@jetbrains/ring-ui-built/components/global/get-uid'
import Shortcuts from '@jetbrains/ring-ui-built/components/shortcuts/shortcuts'
import {toJS} from 'mobx'
import {observer} from 'mobx-react'
import React from 'react'

import {sendStatistics, StatisticsAction} from '../utils/statistics'

import CompletionPopup from './CompletionPopup/CompletionPopup'
import GuidesError from './Guides.error'
import type {GuideError} from './Guides.types'
import {
  checkIfCurrentPathNameIsSameTo,
  expandSidebar,
  getFullHref,
  prepareForNextStep,
  prepareForPrevStep,
  setIntervalImmediately,
} from './Guides.utils'
import useUserActionsController from './hooks/useUserActionsController'
import guidesState from './state/root'

const CHECK_INTERVAL = 1000
const MILLISECONDS_IN_SECOND = 1000
const MAX_CHECKS_COUNT = 15
const SCROLL_BEHAVIOR: ScrollIntoViewOptions = {
  behavior: 'smooth',
  block: 'nearest',
}

const {ReactUI} = window
const {HintPopup} = ReactUI

const GuidesController = observer(() => {
  const [ready, setReady] = React.useState(false)
  const [completed, setCompleted] = React.useState(false)
  const [error, setError] = React.useState<GuideError | null>(null)

  const timestamp = React.useRef(0)

  const attempt = React.useRef(0)
  const timer = React.useRef<number | null>(null)
  const anchorElement = React.useRef<HTMLElement | null>(null)

  const currentStepIndex = guidesState.active.currentActiveStepIndexOrZero
  const {prevStep, currentStep, nextStep} = guidesState.active.guideNearestSteps

  const onClickPrev = React.useCallback(() => {
    if (!guidesState.active.guideId || !currentStep?.id) {
      return
    }

    sendStatistics(StatisticsAction.STEP_FINISH, {
      label: currentStep.id,

      value: (Date.now() - timestamp.current) / MILLISECONDS_IN_SECOND,
      guide_id: guidesState.active.guideId,
      user_id: guidesState.user.id,
    })

    setReady(false)
    setError(null)
    guidesState.progress.setPrevious(guidesState.active.guideId)

    ReactUI.unregisterHint(currentStep.id)
    prepareForPrevStep(prevStep?.requirements)
  }, [currentStep?.id, prevStep?.requirements])

  const onClickNext = React.useCallback(() => {
    if (!guidesState.active.guideId || !currentStep) {
      return
    }

    sendStatistics(StatisticsAction.STEP_FINISH, {
      label: currentStep.id,

      value: (Date.now() - timestamp.current) / MILLISECONDS_IN_SECOND,
      guide_id: guidesState.active.guideId,
      user_id: guidesState.user.id,
    })

    setReady(false)
    setError(null)

    if (!nextStep) {
      setCompleted(true)
    }

    guidesState.progress.setNext(guidesState.active.guideId)

    ReactUI.unregisterHint(currentStep.id)
    prepareForNextStep(currentStep.requirements, nextStep?.requirements)
  }, [currentStep, nextStep])

  const closeGuide = React.useCallback(() => {
    if (!currentStep?.id) {
      return
    }

    sendStatistics(StatisticsAction.STEP_FINISH, {
      label: currentStep.id,

      value: (Date.now() - timestamp.current) / MILLISECONDS_IN_SECOND,
      guide_id: guidesState.active.guideId,
      user_id: guidesState.user.id,
    })

    setError(null)
    guidesState.stop()

    ReactUI.unregisterHint(currentStep.id)
  }, [currentStep?.id])

  const accomplished = useUserActionsController(currentStep, ready, onClickNext)
  const shortcutsMap = React.useMemo(() => ({esc: closeGuide}), [closeGuide])

  React.useEffect(() => {
    const hrefIsCorrect =
      currentStep?.requirements && location.href === getFullHref(currentStep.requirements.context)

    const pathIsCorrect =
      currentStep?.requirements.context.pathname &&
      checkIfCurrentPathNameIsSameTo(currentStep?.requirements.context.pathname)

    const contextIsCorrect =
      pathIsCorrect || hrefIsCorrect || currentStep?.requirements.context.selector

    if (!guidesState.enabled || !currentStep || !contextIsCorrect) {
      return
    }

    if (currentStep.requirements.ui?.forceExpandedSidebar) {
      setTimeout(expandSidebar, CHECK_INTERVAL)
    }

    attempt.current = 0
    anchorElement.current = null

    timer.current = setIntervalImmediately(() => {
      attempt.current++

      if (attempt.current > MAX_CHECKS_COUNT) {
        if (timer.current != null) {
          clearInterval(timer.current)
        }
        timer.current = null

        setError({
          title: `Failed to display guide step [${currentStep.name}].`,
          message: 'Error occurred while trying to find required UI element.',
        })

        return
      }

      anchorElement.current =
        typeof currentStep.selector === 'string'
          ? document.querySelector(currentStep.selector)
          : document.querySelector(`[data-hint-container-id=${currentStep.id}]`)

      if (anchorElement.current) {
        setReady(true)
        if (timer.current != null) {
          clearInterval(timer.current)
        }
        timer.current = null
      }
    }, CHECK_INTERVAL)

    // eslint-disable-next-line consistent-return
    return () => {
      if (timer.current != null) {
        clearInterval(timer.current)
      }
    }
  }, [currentStep])

  React.useEffect(() => {
    if (!guidesState.enabled || !ready || !guidesState.active.guideId || !currentStep) {
      return
    }

    setCompleted(false)

    ReactUI.registerHint({
      ...toJS(currentStep),
      category: 'Guide',
    })

    anchorElement.current?.scrollIntoView(SCROLL_BEHAVIOR)

    timestamp.current = Date.now()
    sendStatistics(StatisticsAction.STEP_VISIT, {
      label: currentStep.id,
      guide_id: guidesState.active.guideId,
      user_id: guidesState.user.id,
    })
  }, [ready, currentStep])

  if (error != null) {
    return (
      <GuidesError
        title={error.title}
        message={error.message}
        onClose={closeGuide}
        onClickNext={onClickNext}
        onClickPrev={prevStep ? onClickPrev : undefined}
      />
    )
  }

  if (completed) {
    return <CompletionPopup />
  }

  if (!guidesState.enabled || !ready || !currentStep) {
    return null
  }

  return (
    <>
      <Shortcuts map={shortcutsMap} scope={getUID('guides')} />
      <HintPopup
        dark
        id={currentStep.id}
        currentIndex={currentStepIndex! + 1}
        total={guidesState.active?.steps?.length}
        btnNextText={!nextStep ? 'Finish' : undefined}
        onClickPrev={prevStep ? onClickPrev : undefined}
        onClickNext={accomplished ? onClickNext : undefined}
        onClose={closeGuide}
      />
    </>
  )
})

export default GuidesController
