import experimentIcon from '@jetbrains/icons/experiment-20px'
import {H1} from '@jetbrains/ring-ui-built/components/heading/heading'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import {Tab, Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import React from 'react'

import tabStyles from '../../../../../components/common/OverviewTab/OverviewTab.module.css'
import {IS_LEARNING_SERVER} from '../../config'
import GuidesList from '../Guides/Guides.list'
import {StorageEntries} from '../Guides/Guides.types'
import useSearchParam from '../hooks/useSearchParam'
import persistedStorage from '../utils/storage'
import Videos from '../Videos/Videos'

import styles from './Overview.module.css'

enum TabId {
  GUIDES = 'guides',
  VIDEOS = 'videos',
}

function Overview() {
  const [selected, setSelected] = useSearchParam('tab', '')

  React.useEffect(() => {
    if (!IS_LEARNING_SERVER) {
      return
    }

    persistedStorage.getValue<string>(StorageEntries.OVERVIEW_LAST_TAB).then(storedState => {
      setSelected(prevState => {
        const tabs = Object.values(TabId)
        const newState = tabs.includes(prevState as TabId)
          ? prevState
          : storedState && tabs.includes(storedState as TabId)
            ? storedState
            : TabId.VIDEOS

        if (newState !== storedState) {
          persistedStorage.setValue(StorageEntries.OVERVIEW_LAST_TAB, newState).catch()
        }

        return newState
      })
    })
  }, [setSelected])

  const handleSelect = React.useCallback(
    async (key: string) => {
      await persistedStorage.setValue(StorageEntries.OVERVIEW_LAST_TAB, key)
      setSelected(key)
    },
    [setSelected],
  )

  return (
    <>
      <H1>{'TeamCity Learning Center'}</H1>
      <div className={styles.content}>
        {!IS_LEARNING_SERVER ? (
          <Videos />
        ) : selected ? (
          <Tabs selected={selected} onSelect={handleSelect} className={tabStyles.tabs}>
            <Tab id={TabId.VIDEOS} title={'Videos'}>
              <Videos />
            </Tab>
            <Tab
              id={TabId.GUIDES}
              title={
                <>
                  <Tooltip title={'This functionality is under development'}>
                    <Icon className={styles.icon} glyph={experimentIcon} />
                  </Tooltip>
                  {'Guides'}
                </>
              }
            >
              <GuidesList />
            </Tab>
          </Tabs>
        ) : (
          <Loader />
        )}
      </div>
    </>
  )
}

export default Overview
