import {makeAutoObservable, runInAction, reaction} from 'mobx'

import persistedStorage from '../../utils/storage'
import {StorageEntries} from '../Guides.types'

import {ActiveGuideState} from './active'
import {AvailableGuidesState} from './available'
import {GuideProgressState} from './progress'
import {UserState} from './user'

export class GuidesState {
  enabled = false

  active
  progress
  available
  user

  constructor() {
    this.hydrate().then(() => {
      reaction(
        () => this.enabled,
        async enabled => await persistedStorage.setValue(StorageEntries.ENABLED, enabled),
      )
    })
    this.user = new UserState()
    this.active = new ActiveGuideState(this)
    this.progress = new GuideProgressState(this)
    this.available = new AvailableGuidesState(this)

    makeAutoObservable(this, {
      active: false,
      progress: false,
      available: false,
    })
  }

  async hydrate() {
    const result = await persistedStorage.getValue<boolean>(StorageEntries.ENABLED)

    runInAction(() => {
      if (result !== undefined) {
        this.enabled = result
      }
    })
  }

  enable() {
    this.enabled = true
  }

  disable() {
    this.enabled = false
  }

  stop() {
    this.disable()
    this.active.reset()
  }
}

const guidesState = new GuidesState()
window.learningPlugin.test.state = guidesState

export default guidesState
