import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'

import ServiceMessage from '../../../../../components/common/ServiceMessage/ServiceMessage'

import styles from './Guides.module.css'

type OwnProps = {
  readonly title: string
  readonly message: string
  readonly onClose?: () => void
  readonly onClickNext?: () => void
  readonly onClickPrev?: () => void
}

function GuidesError({title, message, onClose, onClickPrev, onClickNext}: OwnProps) {
  return (
    <ServiceMessage
      title={title}
      icon={'exception'}
      iconClassName={styles.errorIcon}
      descriptionClassName={styles.errorDescription}
      onCloseRequest={onClose}
      controls={
        <>
          {onClickPrev && (
            <Button className={styles.btnPrev} onClick={onClickPrev} height={ControlsHeight.S}>
              {'Previous step'}
            </Button>
          )}
          {onClickNext && (
            <Button onClick={onClickNext} height={ControlsHeight.S} primary>
              {'Skip step'}
            </Button>
          )}
        </>
      }
    >
      <div data-guide-error>{message}</div>
    </ServiceMessage>
  )
}

export default GuidesError
