import type {VideoItem, Category as CategoryType} from './Videos.types'

export const groupByCategories = (videos: ReadonlyArray<VideoItem>) => {
  const grouped: Record<CategoryType, Array<VideoItem>> = {}

  videos.forEach(video => {
    const {category} = video
    if (!grouped[category]) {
      grouped[category] = []
    }
    grouped[category].push(video)
  })

  return grouped
}
