import {REST} from '@jetbrains/teamcity-ui/dist/services'

enum AvailableStorages {
  LOCAL_STORAGE,
  USER_PROPERTIES_STORAGE,
}

interface Storage {
  get: <T>(key: string) => Promise<T | undefined>
  set: <T>(key: string, value: T) => Promise<void>
  delete: (key: string) => Promise<void>
}

class LocalStorage implements Storage {
  private static readonly PREFIX = 'teamcity.guides'

  async get<T>(key: string): Promise<T | undefined> {
    const value = await localStorage.getItem(`${LocalStorage.PREFIX}.${key}`)
    try {
      return value ? JSON.parse(value) : undefined
    } catch (error) {
      return undefined
    }
  }

  async set(key: string, value: any): Promise<void> {
    await localStorage.setItem(`${LocalStorage.PREFIX}.${key}`, JSON.stringify(value))
  }

  async delete(key: string): Promise<void> {
    await localStorage.removeItem(`${LocalStorage.PREFIX}.${key}`)
    return Promise.resolve()
  }
}

export const safeLocalStorage = new LocalStorage()

const MAX_VALUE_LENGTH = 2000
class UserPropertiesStorage implements Storage {
  private static readonly MAX_VALUE_LENGTH = MAX_VALUE_LENGTH
  private static readonly PREFIX = 'teamcity.plugins.guides'
  private static readonly PROPERTIES_URL = 'app/rest/users/current/properties'

  private static processString(value: string): Array<string> {
    const chunks: string[] = []

    let index = 0
    while (index < value.length) {
      chunks.push(value.substring(index, (index += UserPropertiesStorage.MAX_VALUE_LENGTH)))
    }

    return chunks
  }

  private readonly cache = window.learningPlugin.storage

  async get<T>(key: string): Promise<T | undefined> {
    return await this.cache[key]
  }

  async set<T>(key: string, value: T): Promise<void> {
    const cachedValue = this.cache[key]
    const oldValues =
      cachedValue !== undefined
        ? UserPropertiesStorage.processString(JSON.stringify(cachedValue))
        : []
    const newValues = UserPropertiesStorage.processString(JSON.stringify(value))

    this.cache[key] = value
    const requests: Promise<string>[] = []

    for (let i = 0; i < Math.max(newValues.length, oldValues.length); ++i) {
      const oldValue = oldValues[i]
      const newValue = newValues[i]

      if (oldValue === newValue) {
        continue
      }

      const request = REST.requestText(
        `${UserPropertiesStorage.PROPERTIES_URL}/${UserPropertiesStorage.PREFIX}.${key}.${i}`,
        {
          method: newValue ? 'PUT' : 'DELETE',
          body: newValue,
          headers: {
            Accept: 'text/plain',
          },
        },
      )
      requests.push(request)
    }

    await Promise.all(requests)
  }

  async delete(key: string): Promise<void> {
    const cachedValue = this.cache[key]
    if (cachedValue === undefined) {
      return
    }

    const oldValues = UserPropertiesStorage.processString(JSON.stringify(cachedValue))
    delete this.cache[key]

    const requests = oldValues.map((_, index) =>
      REST.requestText(
        `${UserPropertiesStorage.PROPERTIES_URL}/${UserPropertiesStorage.PREFIX}.${key}.${index}`,
        {
          method: 'DELETE',
        },
      ),
    )

    await Promise.all(requests)
  }
}

class PersistedStorage {
  private strategy: Storage

  constructor(strategy?: AvailableStorages) {
    switch (strategy) {
      case AvailableStorages.LOCAL_STORAGE: {
        this.strategy = new LocalStorage()
        break
      }
      case AvailableStorages.USER_PROPERTIES_STORAGE: {
        this.strategy = new UserPropertiesStorage()
        break
      }
      default: {
        this.strategy = new LocalStorage()
      }
    }
  }

  async getValue<T>(key: string): Promise<T | undefined> {
    return await this.strategy.get<T>(key)
  }

  async delete(key: string): Promise<void> {
    return await this.strategy.delete(key)
  }

  async setValue<T>(key: string, value: T) {
    return await this.strategy.set<T>(key, value)
  }
}

const persistedStorage = new PersistedStorage(
  window.learningPlugin.user.isGuestOrRoot
    ? AvailableStorages.LOCAL_STORAGE
    : AvailableStorages.USER_PROPERTIES_STORAGE,
)

window.learningPlugin.test.persistedStorage = persistedStorage

export type PersistedStorageType = PersistedStorage
export default persistedStorage
