import playIcon from '@jetbrains/icons/play'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import classNames from 'classnames'
import React from 'react'

import useVideoController from '../../hooks/useVideoController'
import styles from '../Videos.module.css'
import type {VideoItem} from '../Videos.types'

const visibilityObserverOptions: IntersectionObserverInit = {
  root: null,
  threshold: 0.1,
}

const noop = () => {}
function VideoItemIframe({video}: {video: VideoItem}) {
  const detectorRef = React.useRef<HTMLDivElement>(null)

  const [loading, setLoading] = React.useState(false)
  const [visible, setVisible] = React.useState(false)
  const [showPlaceholder, setShowPlaceholder] = React.useState(true)

  useVideoController(!showPlaceholder ? video.link.id : null)

  React.useEffect(() => {
    const detector = detectorRef.current

    if (!detector) {
      return noop
    }

    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          observer.unobserve(detector)
          setVisible(true)
        }
      })
    }, visibilityObserverOptions)

    observer.observe(detector)

    return () => {
      observer.unobserve(detector)
    }
  }, [video.name])

  const onPlaceholderClick = React.useCallback(() => {
    setLoading(true)
    setShowPlaceholder(false)
  }, [])

  return visible ? (
    <div className={classNames(styles.wrapper, video.featured && styles.featured)}>
      <div
        className={classNames(
          styles.placeholder,
          loading && styles.loading,
          !showPlaceholder && !loading && styles.hidden,
        )}
      >
        <Button
          className={classNames(styles.btnPlay, loading && styles.hidden)}
          icon={playIcon}
          loader={loading}
          onClick={onPlaceholderClick}
        />
        <img
          className={classNames(styles.iframe, styles.image)}
          src={`https://i.ytimg.com/vi_webp/${video.link.id}/maxresdefault.webp`}
          alt={`${video.name} Thumbnail`}
        />
      </div>
      {!showPlaceholder && (
        <iframe
          id={video.link.id}
          src={`https://www.youtube.com/embed/${video.link.id}?enablejsapi=1`}
          className={classNames(styles.iframe, loading && styles.hidden)}
          title={video.name}
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
          allowFullScreen
          onLoad={() => setLoading(false)}
        />
      )}
    </div>
  ) : (
    <div ref={detectorRef} />
  )
}

export default VideoItemIframe
