import {reaction, makeAutoObservable, toJS, runInAction} from 'mobx'

import persistedStorage from '../../utils/storage'
import type {GuideId, GuidesProgressInfo, GuideStep} from '../Guides.types'
import {StorageEntries} from '../Guides.types'

import type {GuidesState} from './root'

export class GuideProgressState {
  root: GuidesState
  list: GuidesProgressInfo = {}

  constructor(root: GuidesState) {
    this.hydrate().then(() =>
      reaction(
        () => toJS(this.list),
        async list => {
          await persistedStorage.setValue(StorageEntries.PROGRESS, list)
        },
      ),
    )
    this.root = root

    makeAutoObservable(this, {
      root: false,
    })
  }

  async hydrate() {
    const progress = await persistedStorage.getValue<GuidesProgressInfo>(StorageEntries.PROGRESS)

    runInAction(() => {
      if (progress) {
        this.list = progress
      }
    })
  }

  resetProgress(guideId: GuideId) {
    if (this.list?.[guideId]) {
      delete this.list[guideId]
    }
  }

  findByGuideId(guideId: GuideId) {
    return this.list?.[guideId] ?? null
  }

  addCompletedStep(guideId: GuideId, stepId: GuideStep['id'] | null) {
    if (stepId == null) {
      return
    }

    const guide = this.findByGuideId(guideId)
    if (!guide.completed.includes(stepId)) {
      guide.completed.push(stepId)
    }
  }

  setPrevious(guideId: GuideId) {
    const {prevStep, currentStep} = this.root.active.guideNearestSteps
    const current = this.findByGuideId(guideId)
    current.currentStep = prevStep?.id ?? currentStep?.id ?? null
  }

  setNext(guideId: GuideId) {
    const {nextStep, currentStep} = this.root.active.guideNearestSteps
    const guideProgress = this.findByGuideId(guideId)

    if (nextStep == null) {
      this.root.active.reset()
      this.root.disable()
    }

    if (guideProgress) {
      guideProgress.currentStep = nextStep?.id ?? currentStep?.id ?? null
      this.addCompletedStep(guideId, currentStep?.id ?? null)
    } else {
      this.list[guideId] = {
        currentStep: nextStep?.id ?? currentStep?.id ?? null,
        completed: currentStep?.id ? [currentStep?.id] : [],
      }
    }
  }
}
