import type {HintId} from '../../types'

import type {GuideStep} from './Guides.types'

export const findGuideStepIndexOrZero = (
  steps: ReadonlyArray<GuideStep> | null,
  stepId: HintId | null,
) => {
  if (!steps) {
    return 0
  }

  const index = steps.findIndex(item => item.id === stepId) ?? 0
  return index < 0 ? 0 : index
}

type GuideNearestSteps = {
  prevStep: GuideStep | null
  currentStep: GuideStep | null
  nextStep: GuideStep | null
}

export const nullSteps: GuideNearestSteps = {
  prevStep: null,
  currentStep: null,
  nextStep: null,
}
export const getGuideNearestSteps = (
  steps: ReadonlyArray<GuideStep> | undefined,
  currentStep: HintId | null,
): GuideNearestSteps => {
  if (!steps) {
    return nullSteps
  }

  const index = findGuideStepIndexOrZero(steps, currentStep)

  return {
    prevStep: steps[index - 1] ?? null,
    currentStep: steps[index] ?? null,
    nextStep: steps[index + 1] ?? null,
  }
}
