import Dialog from '@jetbrains/ring-ui-built/components/dialog/dialog'
import {H1} from '@jetbrains/ring-ui-built/components/heading/heading'
import {AlertService} from '@jetbrains/teamcity-ui/dist/services'
import {observer} from 'mobx-react'
import React from 'react'

import GuideItem from '../GuideItem/GuideItem'
import type {Guide} from '../Guides.types'
import {fetchGuides} from '../Guides.utils'
import guidesState from '../state/root'

import styles from './Guides.launcher.module.css'

const ERROR_ALERT_TIMEOUT = 5000

const GuidesLauncher = observer(() => {
  const [guide, setGuide] = React.useState<Guide | null>(null)
  const closeHandle = React.useCallback(() => setGuide(null), [])

  React.useEffect(() => {
    const params = new URLSearchParams(location.search)
    const guideId = params.get('guideId')
    const fetch = async () => {
      if (guideId && !guidesState.enabled) {
        const availableGuide = guidesState.available.getGuideById(guideId)

        if (availableGuide) {
          setGuide(availableGuide)
          return
        }

        const guides = await fetchGuides()
        guidesState.available.setAvailableGuides(guides)
        const searchResult = guides.find(item => item.id === guideId)

        if (searchResult) {
          setGuide(searchResult)
          return
        }

        AlertService.error(
          `Failed to find guide with specified id [${guideId}]`,
          ERROR_ALERT_TIMEOUT,
        )
      }
    }

    fetch().catch()
  }, [])

  if (!guide) {
    return null
  }

  return (
    <Dialog
      trapFocus
      showCloseButton
      show={Boolean(guide)}
      autoFocusFirst={false}
      onCloseAttempt={closeHandle}
      contentClassName={styles.launcherContent}
    >
      <H1 className={styles.launcherTitle}>{'Suggested Lesson'}</H1>
      <GuideItem {...guide} onStart={closeHandle} disableStartLink />
    </Dialog>
  )
})

export default GuidesLauncher
