import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import React from 'react'

import Video from './VideoItem/VideoItem'
import videos from './videos.list'
import {groupByCategories} from './Videos.utils'

import styles from './Videos.module.css'

const sorted = [...videos].sort((a, b) => {
  if (a.featured && !b?.featured) {
    return -1
  }

  if (!a.featured && b.featured) {
    return 1
  }

  return 0
})
const grouped = groupByCategories(sorted)

function Videos() {
  const element = React.useMemo(
    () =>
      Object.entries(grouped).map(([category, collection]) => (
        <React.Fragment key={category}>
          <H2 className={styles.category}>{category}</H2>
          <div className={styles.container}>
            {collection.map(video => (
              <Video key={video.name} video={video} />
            ))}
          </div>
        </React.Fragment>
      )),
    [],
  )

  // This fixes the weird Typing error, when Element[] is not a valid children

  return <>{element}</>
}

export default Videos
