import Loader from '@jetbrains/ring-ui-built/components/loader/loader'
import classNames from 'classnames'
import {observer} from 'mobx-react'
import React from 'react'

import GuideItem from './GuideItem/GuideItem'
import useFetchGuides from './hooks/useFetchGuides'
import rootState from './state/root'

import styles from './Guides.module.css'

type OwnProps = {
  readonly compact?: boolean
  readonly className?: string
}

const GuidesList = observer(({compact, className}: OwnProps): React.ReactElement => {
  const {guides, loading, error} = useFetchGuides()

  React.useEffect(() => {
    rootState.available.setAvailableGuides(guides)
  }, [guides])

  const classes = classNames(styles.guides, compact ? styles.shortList : null, className)

  if (error) {
    // eslint-disable-next-line no-console
    console.error(error)
    return <div>{'Oops! Something wrong'}</div>
  }

  return loading ? (
    <Loader />
  ) : (
    <div className={classes}>
      {rootState.available.list.map(guide => (
        <GuideItem key={`${guide.id}-${guide.title}`} {...guide} />
      ))}
    </div>
  )
})

export default GuidesList
