import TeamCityLogo from '@jetbrains/logos/teamcity/teamcity.svg'
import React from 'react'

import styles from './GuideItem.module.css'

type OwnProps = {
  src?: string
  alt?: string
}
function GuideItemImage({src, alt}: OwnProps) {
  const [error, setError] = React.useState(false)
  const imageRef = React.useRef<HTMLImageElement>(null)

  React.useEffect(() => {
    const image = imageRef.current

    if (!image) {
      return
    }

    image.onerror = () => setError(true)
  }, [])

  if (!src || error) {
    return <TeamCityLogo className={styles.image} />
  }

  return <img className={styles.image} src={src} alt={alt} ref={imageRef} />
}

export default GuideItemImage
