import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import classNames from 'classnames'

import Tags from '../../common/Tags/Tags'
import styles from '../Videos.module.css'
import type {VideoItem} from '../Videos.types'

import VideoItemIframe from './VideoItem.iframe'

type OwnProps = {
  video: VideoItem
}

function Video({video}: OwnProps) {
  return (
    <div className={classNames(styles.item, video.featured && styles.featured)}>
      <VideoItemIframe key={video.name} video={video} />
      <div className={styles.description}>
        <H2 className={classNames(styles.title)}>{video.name}</H2>
        {video.featured && <div className={styles.meta}>{video.description}</div>}
        <Tags tags={video.tags} />
      </div>
    </div>
  )
}

export default Video
