import {makeAutoObservable, runInAction, reaction} from 'mobx'

import {safeLocalStorage} from '../../utils/storage'
import {findGuideStepIndexOrZero, getGuideNearestSteps, nullSteps} from '../Guides.selectors'
import type {ActiveGuide, GuideId, GuideStep} from '../Guides.types'
import {StorageEntries} from '../Guides.types'

import type {GuidesState} from './root'

export class ActiveGuideState {
  root: GuidesState

  guideId: GuideId | null = null
  steps: ReadonlyArray<GuideStep> = []

  constructor(root: GuidesState) {
    this.hydrate().then(() => {
      reaction(
        () => this.guideId,
        async guideId => {
          if (guideId == null) {
            await safeLocalStorage.delete(StorageEntries.ACTIVE_GUIDE)
            return
          }

          await safeLocalStorage.set(StorageEntries.ACTIVE_GUIDE, {
            id: this.guideId,
            steps: this.steps,
          })
        },
      )
    })
    this.root = root

    makeAutoObservable(this, {
      root: false,
    })
  }

  reset() {
    this.guideId = null
    this.steps = []
  }

  async hydrate() {
    const activeGuide = await safeLocalStorage.get<ActiveGuide>(StorageEntries.ACTIVE_GUIDE)

    runInAction(() => {
      if (activeGuide) {
        this.guideId = activeGuide.id
        this.steps = activeGuide.steps
      }
    })
  }

  setActive(activeGuide: ActiveGuide) {
    this.guideId = activeGuide.id
    this.steps = activeGuide.steps
    this.root.enable()
  }

  get currentActiveStepIndexOrZero() {
    if (!this.guideId) {
      return null
    }

    const currentStepId = this.root.progress.findByGuideId(this.guideId)?.currentStep ?? null
    return findGuideStepIndexOrZero(this?.steps ?? null, currentStepId)
  }

  get guideNearestSteps() {
    if (!this.guideId) {
      return nullSteps
    }

    const currentStepId = this.root.progress.findByGuideId(this.guideId)?.currentStep ?? null
    return getGuideNearestSteps(this.steps, currentStepId)
  }
}
