import type {HintId, HintType} from '../../types'

export type GuideId = string
type GuideImage = {
  readonly src: string
  readonly alt: string
}

export type GuideStepContextRequirements = Readonly<{
  href?: string
  pathname?: string
  entityId?: string
  entityType?: string
  selector?: {
    buildTypeId: string
    projectId?: string
    state?: string
    status?: string
    tag?: string
  }
}>

type GuideStepUIElement = Readonly<
  {
    selector: string
  } & (
    | {type: 'select'; selectedIndex: number}
    | {type: 'checkbox' | 'radio'; checked: boolean}
    | {type: 'text' | 'textarea'; value: string}
  )
>

export type GuideStepUIAction = Readonly<{
  type: 'click' | 'focus'
  selector: string
  actor?: 'user' | 'auto'
  triggerNextStep?: boolean
  disableAutoRedirect?: boolean
}>

export type GuideStepUIRequirements = Readonly<{
  forceExpandedSidebar?: boolean
  actions?: Array<GuideStepUIAction>
  elements?: Array<GuideStepUIElement>
}>

export type GuideStepRequirements = Readonly<{
  context: GuideStepContextRequirements
  ui?: GuideStepUIRequirements
  permissions?: Array<string>
}>

export type GuideStep = HintType & {
  readonly requirements: GuideStepRequirements
}

export type Guide = {
  readonly id: GuideId
  readonly steps: ReadonlyArray<GuideStep>
  readonly tags?: ReadonlyArray<string>
  readonly projectId?: string
  readonly title: string
  readonly description: string
  readonly duration: number
  readonly image?: GuideImage
  readonly className?: string
}

type GuideStepInput = Omit<GuideStep, 'id'> & {
  id?: string
}

export type GuideInput = Omit<Guide, 'steps'> & {
  readonly steps: ReadonlyArray<GuideStepInput>
}

export type GuideError = {
  title: string
  message: string
}

type GuideProgress = {
  currentStep: HintId | null
  completed: Array<HintId>
}
export type GuidesProgressInfo = Record<GuideId, GuideProgress>
export type ActiveGuide = Pick<Guide, 'id' | 'steps'>

export enum StorageEntries {
  ACTIVE_GUIDE = 'activeGuide',
  PROGRESS = 'progress',
  ENABLED = 'enabled',
  USER_ID = 'uid',
  UTM_SOURCE = 'source',
  OVERVIEW_LAST_TAB = 'overviewTab',
}
