/* eslint-disable no-new */
import {Plugin} from '@jetbrains/teamcity-ui'

import GuidesController from './Components/Guides/Guides.controller'
import GuidesLauncher from './Components/Guides/Launcher/Guides.launcher'
import ProjectLink from './Components/Guides/ProjectLink/ProjectLink'
import HeaderLink from './Components/HeaderLink/HeaderLink'
import Overview from './Components/Overview/Overview'
import {IS_PLUGIN_ENABLED, IS_LEARNING_SERVER} from './config'

import styles from './globals.module.css'

if (IS_PLUGIN_ENABLED) {
  new Plugin(Plugin.placeIds.SAKURA_GUIDES_OVERVIEW, {
    name: 'Guides Overview',
    content: Overview,
    options: {
      containerClassNames: [styles.guidesPluginContainer],
      _internal: true,
    },
  })

  new Plugin(Plugin.placeIds.SAKURA_HEADER_NAVIGATION_AFTER, {
    name: 'Guides Header Link',
    content: HeaderLink,
    options: {_internal: true},
  })

  if (IS_LEARNING_SERVER) {
    new Plugin(Plugin.placeIds.SAKURA_PROJECT_LINKS, {
      name: 'Guides Project Link',
      content: ProjectLink,
      options: {_internal: true},
    })

    new Plugin(Plugin.placeIds.SAKURA_HEADER_RIGHT, {
      name: 'Guides Launcher',
      content: GuidesLauncher,
      options: {_internal: true},
    })

    window.ReactUI.renderConnected('guides-container', GuidesController, {})
  }
}
