import React from 'react'

class VideoController {
  private readonly API_URL = 'https://www.youtube.com/iframe_api'

  private players = new Map<string, YT.Player>()
  private currentPlayer: YT.Player | null = null
  private api: Promise<typeof YT> | null = null

  private loadApi(): Promise<typeof YT> {
    if (this.api == null) {
      this.api = new Promise((resolve, reject) => {
        if (window.YT != null) {
          resolve(window.YT)
          return
        }

        const script = document.createElement('script')
        script.id = 'yt-api'
        script.src = this.API_URL
        script.onerror = () => {
          reject('Failed to load YouTube Iframe API')
        }
        document.head.appendChild(script)

        window.onYouTubeIframeAPIReady = () => {
          resolve(window.YT)
        }
      })
    }

    return this.api
  }

  private onPlayerReady(event: YT.PlayerEvent) {
    event.target.playVideo()
  }

  private onPlayerStateChange(event: YT.OnStateChangeEvent) {
    if (event.data !== YT.PlayerState.PLAYING) {
      return
    }

    if (
      this.currentPlayer !== event.target &&
      this.currentPlayer?.getPlayerState() === YT.PlayerState.PLAYING
    ) {
      this.currentPlayer.pauseVideo()
    }
    this.currentPlayer = event.target
  }

  async createPlayer(id: string) {
    const YT = await this.loadApi()
    const newPlayer = new YT.Player(id, {
      events: {
        onReady: this.onPlayerReady.bind(this),
        onStateChange: this.onPlayerStateChange.bind(this),
      },
    })
    this.players.set(id, newPlayer)
  }

  deletePlayer(id: string) {
    this.players.delete(id)
  }
}
const videoController = new VideoController()

export default (videoId: string | null) => {
  React.useEffect(() => {
    if (videoId == null) {
      return () => {}
    }

    // eslint-disable-next-line no-console
    videoController.createPlayer(videoId).catch(err => console.error(err))

    return () => videoController.deletePlayer(videoId)
  }, [videoId])
}
