import Button from '@jetbrains/ring-ui-built/components/button/button'
import {ControlsHeight} from '@jetbrains/ring-ui-built/components/global/controls-height'
import React from 'react'

import ServiceMessage from '../../../../../../components/common/ServiceMessage/ServiceMessage'
import {LEARNING_CENTER_URL} from '../../../config'
import styles from '../Guides.module.css'

function CompletionPopup() {
  const onClick = React.useCallback(() => {
    location.href = LEARNING_CENTER_URL
  }, [])

  return (
    <ServiceMessage
      title={'Lesson completed'}
      icon={'checkmark'}
      iconClassName={styles.successIcon}
      controls={
        <Button onClick={onClick} height={ControlsHeight.S} primary>
          {'Return to the Learning Center'}
        </Button>
      }
    >
      <div>{'You have successfully completed the lesson. Great job!'}</div>
    </ServiceMessage>
  )
}

export default CompletionPopup
