import Button from '@jetbrains/ring-ui-built/components/button/button'
import type {PluginContext} from '@jetbrains/teamcity-ui'
import {runInAction} from 'mobx'
import {observer} from 'mobx-react'
import React from 'react'

import {launchGuide} from '../Guides.utils'
import useFetchGuides from '../hooks/useFetchGuides'
import rootState from '../state/root'

import styles from './ProjectLink.module.css'

type OwnProps = PluginContext

const ProjectLink = observer(({location: {projectId}}: OwnProps) => {
  if (!projectId) {
    return null
  }

  const {guides} = useFetchGuides(projectId)

  if (guides.length) {
    runInAction(() => {
      guides.forEach(guide => rootState.available.registerGuide(guide))
    })
  }

  const guide = rootState.available.getGuideByProjectId(projectId)
  const handleClick = React.useCallback(() => {
    if (guide?.id) {
      launchGuide(guide.id)
    }
  }, [guide?.id])

  return guide ? (
    <Button className={styles.button} onClick={handleClick}>{`Start tutorial`}</Button>
  ) : null
})

export default ProjectLink
