import TeamCityAPI from '@jetbrains/teamcity-ui'

import bundledGuides from './guides.json'
import {getGuideNearestSteps} from './Guides.selectors'
import type {
  Guide,
  GuideId,
  GuideStep,
  GuideStepUIRequirements,
  GuideStepContextRequirements,
  GuideStepRequirements,
  GuideInput,
} from './Guides.types'
import root from './state/root'

type APIResponseBuilds = {
  build: Array<{id: string}>
}
type APIResponseGuides = Array<{
  projectId?: string
  content: string
  guideId?: string
}>

export const getFullHref = ({href, pathname}: GuideStepContextRequirements): string | null => {
  if (href) {
    return window.base_uri + (href.startsWith('/') ? href : `/${href}`)
  }

  if (pathname) {
    return window.base_uri + pathname
  }

  return null
}

export const checkIfCurrentPathNameIsSameTo = (pathname: string) =>
  `${document.location.origin}${document.location.pathname}` === `${window.base_uri}${pathname}`

const redirect = (href: string) => {
  if (href !== location.href) {
    location.replace(href)
  }
}

export const setIntervalImmediately = (handler: () => void, timeout: number) => {
  setTimeout(handler)
  return window.setInterval(handler, timeout)
}

const requestBuild = async ({
  buildTypeId,
  status = 'success',
  state = 'finished',
  tag = '',
}: NonNullable<GuideStepContextRequirements['selector']>) => {
  const data = await TeamCityAPI.utils.requestJSON<APIResponseBuilds>(
    `/app/rest/ui/builds?locator=state:(${state}),status:(${status}),tag:${tag},buildType:(id:${buildTypeId}),count:1`,
  )

  return data?.build?.[0]
}

const prepareStepLink = async (requirements: GuideStepContextRequirements) => {
  let url = null

  if (requirements.href || requirements.pathname) {
    url = getFullHref(requirements)
  }

  if (requirements.selector) {
    const build = await requestBuild(requirements.selector)

    if (build?.id) {
      url = getFullHref({pathname: `/build/${build.id}`})
    }
  }

  return url
}

export const createGuideShareLink = async (id: GuideId, step: GuideStep) => {
  const stepLink = await prepareStepLink(step.requirements.context)
  const url = new URL(stepLink ?? location.href)

  url.searchParams.set('guideId', id)

  return url.toString()
}

const checkIfShouldRedirect = (requirements: GuideStepContextRequirements) => {
  if (requirements.pathname) {
    return !checkIfCurrentPathNameIsSameTo(requirements.pathname)
  }

  return true
}

const processUIRequirements = (requirements: GuideStepUIRequirements) => {
  requirements.elements?.forEach(req => {
    const element = document.querySelector(req.selector)

    if (!element) {
      return
    }

    switch (req.type) {
      case 'select':
        if (element instanceof HTMLSelectElement) {
          element.selectedIndex = req.selectedIndex
        }
        break
      case 'radio':
      case 'checkbox':
        if (
          element instanceof HTMLInputElement &&
          ((!element.checked && req.checked) || (element.checked && !req.checked))
        ) {
          element.click()
        }
        break
      case 'text':
      case 'textarea':
        if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) {
          element.value = req.value
        }
        break
      default:
        break
    }
  })

  requirements.actions?.forEach(action => {
    if (action.actor === 'user') {
      return
    }

    const element = document.querySelector<HTMLElement>(action.selector)

    switch (action.type) {
      case 'click':
        element?.click()
        break
      case 'focus':
        element?.focus()
        break
      default:
        break
    }
  })
}

const processContextRequirements = async (requirements: GuideStepContextRequirements) => {
  const url = await prepareStepLink(requirements)
  const shouldRedirect = checkIfShouldRedirect(requirements)

  if (url && shouldRedirect) {
    redirect(url)
  }
}

export const prepareForNextStep = async (
  currentStepReqs?: GuideStepRequirements | null,
  nextStepReqs?: GuideStepRequirements | null,
) => {
  if (currentStepReqs?.ui) {
    processUIRequirements(currentStepReqs.ui)
  }

  const actions = currentStepReqs?.ui?.actions
  const lastAction = actions?.[actions?.length - 1]

  if (nextStepReqs && !lastAction?.disableAutoRedirect) {
    await processContextRequirements(nextStepReqs.context)
  }
}

export const prepareForPrevStep = async (prevStepReqs?: GuideStepRequirements | null) => {
  if (prevStepReqs) {
    await processContextRequirements(prevStepReqs.context)
  }
}

const isValidGuide = (item: any) => item.id && item.title && item.steps.length > 0
const processGuideSteps = (guide: GuideInput): Guide =>
  ({
    ...guide,
    steps: guide.steps.map((step, index) => (step.id ? step : {...step, id: `step-#${index + 1}`})),
  }) as Guide

export const fetchGuides = async (projectId: string | null = '') => {
  const ALL_GUIDES_ENDPOINT = 'app/learning/guides/all'
  const PROJECT_GUIDES_ENDPOINT = 'app/learning/guides/project'

  const guidesList: Guide[] = []
  const data = await TeamCityAPI.utils.requestJSON<APIResponseGuides>(
    projectId ? `${PROJECT_GUIDES_ENDPOINT}/${projectId}` : ALL_GUIDES_ENDPOINT,
  )

  data.forEach(item => {
    try {
      const guide = {
        projectId: item.projectId ?? null,
        id: item.guideId ?? null,
        ...JSON.parse(item.content),
      }

      if (isValidGuide(guide)) {
        guidesList.push(guide)
      }
    } catch {
      // ignore data with wrong format
    }
  })

  return (projectId ? guidesList : [...(bundledGuides as GuideInput[]), ...guidesList]).map(guide =>
    processGuideSteps(guide),
  )
}

export const launchGuide = (id: GuideId) => {
  const progress = root.progress.findByGuideId(id)
  const guide = root.available.getGuideById(id)

  if (!guide) {
    return
  }

  root.active.setActive({id, steps: guide.steps})

  const {currentStep, nextStep} = getGuideNearestSteps(guide.steps, progress?.currentStep ?? null)
  const continueLesson =
    nextStep || (currentStep?.id && !progress?.completed.includes(currentStep.id))
  const step = continueLesson ? currentStep : guide.steps[0]

  if (!continueLesson) {
    root.progress.resetProgress(id)
  }

  if (step) {
    processContextRequirements(step.requirements.context)
  }
}

export const expandSidebar = () => {
  const showSidebarBtn = document.querySelector<HTMLButtonElement>(
    'aside button[title="Show sidebar"]',
  )

  showSidebarBtn?.click()
}
