import learnIcon from '@jetbrains/icons/learn-20px.svg'
import Theme, {useThemeClasses} from '@jetbrains/ring-ui-built/components/global/theme'
import Icon from '@jetbrains/ring-ui-built/components/icon/icon'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/position'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'

import styles from './HeaderLink.module.css'

function HeaderLink() {
  const active = document.location.pathname.includes('/learn')
  const themeClasses = useThemeClasses(Theme.DARK)
  const link = (
    <Link
      className={classNames(styles.link, active ? styles.active : null)}
      href={`${window.base_uri}/learn`}
    >
      <Icon className={styles.icon} glyph={learnIcon} />
      {'Learn'}
    </Link>
  )

  return (
    <Tooltip
      delay={100}
      title="Learn"
      popupProps={{
        directions: [Directions.RIGHT_BOTTOM],
        top: 8,
        offset: 8,
        className: classNames(styles.tooltip, themeClasses),
      }}
    >
      {link}
    </Tooltip>
  )
}

export default HeaderLink
