import {makeAutoObservable, runInAction, reaction} from 'mobx'
import * as uuid from 'uuid'

import {safeLocalStorage} from '../../utils/storage'
import {StorageEntries} from '../Guides.types'

const UUID_VERSION = 4
const isValidId = (id: string, version = UUID_VERSION) =>
  uuid.validate(id) && uuid.version(id) === version

const getUtmSource = () => new URLSearchParams(location.search).get('utm_source')

export class UserState {
  id?: string
  source?: string | null

  constructor() {
    this.hydrate().then(() => {
      reaction(
        () => this.id,
        userId => userId && safeLocalStorage.set(StorageEntries.USER_ID, userId),
      )
      reaction(
        () => this.source,
        source => source && safeLocalStorage.set(StorageEntries.UTM_SOURCE, source),
      )

      if (!this.id) {
        runInAction(() => {
          this.id = uuid.v4()
        })
      }

      const utmSource = getUtmSource()
      if (utmSource) {
        this.source = utmSource
      }
    })

    makeAutoObservable(this)
  }

  async hydrate() {
    const userId = await safeLocalStorage.get<string>(StorageEntries.USER_ID)
    const source = await safeLocalStorage.get<string>(StorageEntries.UTM_SOURCE)

    runInAction(() => {
      if (userId && isValidId(userId)) {
        this.id = userId
      }
      if (source) {
        this.source = source
      }
    })
  }
}
