import React from 'react'

import type {GuideStep, GuideStepUIAction} from '../Guides.types'

function noop() {}

export default (step: GuideStep | null, ready: boolean, triggerNext: () => void) => {
  const [accomplished, setAccomplished] = React.useState(false)
  const [currentActionIndex, setCurrentActionIndex] = React.useState(0)

  const userActions = React.useMemo(() => {
    const actions: GuideStepUIAction[] = []

    step?.requirements.ui?.actions?.forEach(action => {
      if (action.actor === 'user') {
        actions.push(action)
      }
    })

    return actions
  }, [step?.requirements.ui?.actions])

  const currentTarget = React.useMemo(
    () => (ready ? document.querySelector(userActions[currentActionIndex]?.selector) : null),
    [userActions, currentActionIndex, ready],
  )

  const listener = React.useCallback(() => {
    setCurrentActionIndex(prevState => prevState + 1)
  }, [])

  React.useEffect(() => {
    if (userActions.length === currentActionIndex) {
      setAccomplished(true)

      if (currentActionIndex !== 0) {
        if (userActions[currentActionIndex - 1].triggerNextStep) {
          triggerNext()
        }
        setCurrentActionIndex(0)
      }

      return noop
    }

    const eventType = userActions[currentActionIndex]?.type
    currentTarget?.addEventListener(eventType, listener, {once: true})

    return () => currentTarget?.removeEventListener(eventType, listener)
  }, [userActions, listener, currentTarget, currentActionIndex, triggerNext])

  React.useEffect(() => {
    if (userActions.length > 0) {
      setAccomplished(false)
    }
  }, [userActions])

  return accomplished
}
