import {REST} from '@jetbrains/teamcity-ui/dist/services'

export enum StatisticsAction {
  STEP_VISIT = 'step_visit',
  STEP_FINISH = 'step_finish',
}

const STATISTICS_ENDPOINT = 'app/learning/guides/statistics'

export const sendStatistics = async (action: StatisticsAction, payload: Record<string, any>) => {
  await REST.requestText(STATISTICS_ENDPOINT, {
    method: 'POST',
    body: JSON.stringify({
      action,
      category: 'guides',
      ...payload,
    }),
  })
}
